function validate(input) {
  const [{ World = [] }] = input;
  const names = new Set();
  for (const [name, , area, population, gdp] of World) {
    if (name === null) return 'Every country needs a name.';
    const key = String(name).toLowerCase();
    if (names.has(key)) return `${name} appears twice in World.`;
    names.add(key);
    if ([area, population, gdp].some(v => v !== null && v < 0)) return `${name} has a negative value.`;
  }
  return null;
}

