function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const pool = ['Afghanistan', 'Albania', 'Algeria', 'Andorra', 'Angola', 'Brazil', 'Chad', 'Fiji', 'India', 'Peru'];
  const continents = ['Asia', 'Europe', 'Africa', 'America', 'Oceania'];
  // Values cluster around both limits so the inclusive boundaries are exercised.
  const areas = [468, 28748, 652230, 2999999, 3000000, 3000001, 9596961];
  const people = [78115, 2831741, 24999999, 25000000, 25000001, 37100000, 1400000000];
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 9) : 2000;
  const World = [];
  for (let i = 0; i < count; i++) {
    const name = small ? pool[i] ?? `Land ${i}` : `Country ${i + 1}`;
    const area = small || rand() < 0.5 ? pick(areas) : Math.floor(rand() * 10000000);
    const population = small || rand() < 0.5 ? pick(people) : Math.floor(rand() * 60000000);
    World.push([name, pick(continents), area, population, Math.floor(rand() * 2e12)]);
  }
  return [{ World }];
}
